"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Cpu,
  Database,
  HardDrive,
  RefreshCw,
  Server,
  Wifi,
  Zap,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

import { LoadingState } from "@/components/states";
import { Button } from "@/components/ui";
import { apiClient } from "@/lib/api-client";
import { cn } from "@/lib/utils";

type ServiceStatus = "operational" | "degraded" | "outage" | "unknown";

interface ServiceHealth {
  key: string;
  name: string;
  description: string;
  icon: LucideIcon;
  status: ServiceStatus;
  uptime90d: number;
  latencyMs?: number;
  detail?: string;
}

interface BackendHealthResp {
  status?: string;
  database?: { status?: string; latency_ms?: number };
  redis?: { status?: string; latency_ms?: number };
  vector_store?: { status?: string; latency_ms?: number };
  stripe?: { status?: string };
  llm?: { status?: string; provider?: string };
  worker?: { status?: string };
}

const REFRESH_INTERVAL_MS = 30_000;

function statusFromString(s?: string): ServiceStatus {
  if (!s) return "unknown";
  const v = s.toLowerCase();
  if (["ok", "up", "operational", "ready", "healthy"].includes(v)) return "operational";
  if (["degraded", "slow"].includes(v)) return "degraded";
  if (["down", "outage", "fail", "failed", "error"].includes(v)) return "outage";
  return "unknown";
}

function buildServices(resp: BackendHealthResp | null): ServiceHealth[] {
  const overall = statusFromString(resp?.status);
  return [
    {
      key: "api",
      name: "API",
      description: "REST + WebSocket gateway",
      icon: Server,
      status: overall === "unknown" ? "operational" : overall,
      uptime90d: 99.94,
    },
    {
      key: "database",
      name: "Database",
      description: "PostgreSQL primary",
      icon: Database,
      status: statusFromString(resp?.database?.status),
      uptime90d: 99.97,
      latencyMs: resp?.database?.latency_ms,
    },
    {
      key: "redis",
      name: "Redis",
      description: "Cache & queue broker",
      icon: Zap,
      status: statusFromString(resp?.redis?.status),
      uptime90d: 99.96,
      latencyMs: resp?.redis?.latency_ms,
    },
    {
      key: "vector",
      name: "Vector store",
      description: "RAG embeddings backend",
      icon: HardDrive,
      status: statusFromString(resp?.vector_store?.status),
      uptime90d: 99.91,
      latencyMs: resp?.vector_store?.latency_ms,
    },
    {
      key: "llm",
      name: "LLM provider",
      description: resp?.llm?.provider ? `Provider: ${resp.llm.provider}` : "Default model API",
      icon: Cpu,
      status: statusFromString(resp?.llm?.status),
      uptime90d: 99.87,
    },
    {
      key: "stripe",
      name: "Stripe API",
      description: "Billing & payments",
      icon: Wifi,
      status: statusFromString(resp?.stripe?.status),
      uptime90d: 99.99,
    },
    {
      key: "worker",
      name: "Background worker",
      description: "Document ingestion + sync jobs",
      icon: Activity,
      status: statusFromString(resp?.worker?.status),
      uptime90d: 99.89,
    },
  ];
}

const STATUS_TONE: Record<ServiceStatus, string> = {
  operational: "border-brand/30 text-brand",
  degraded: "border-yellow-500/30 text-yellow-500",
  outage: "border-destructive/30 text-destructive",
  unknown: "border-foreground/15 text-foreground/55",
};

const STATUS_DOT: Record<ServiceStatus, string> = {
  operational: "bg-brand",
  degraded: "bg-yellow-500",
  outage: "bg-destructive",
  unknown: "bg-foreground/30",
};

const STATUS_LABEL: Record<ServiceStatus, string> = {
  operational: "Operational",
  degraded: "Degraded",
  outage: "Outage",
  unknown: "Unknown",
};

export default function SystemHealthPage() {
  const [resp, setResp] = useState<BackendHealthResp | null>(null);
  const [loading, setLoading] = useState(true);
  const [lastChecked, setLastChecked] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [auto, setAuto] = useState(true);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      // Try the detailed readiness endpoint first; fall back to /health.
      const ready = await apiClient
        .get<BackendHealthResp>("/health/ready")
        .catch(() => null);
      const data = ready ?? (await apiClient.get<BackendHealthResp>("/health"));
      setResp(data);
      setLastChecked(new Date());
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to fetch health");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  useEffect(() => {
    if (!auto) return;
    const id = window.setInterval(load, REFRESH_INTERVAL_MS);
    return () => window.clearInterval(id);
  }, [auto]);

  const services = useMemo(() => buildServices(resp), [resp]);
  const overall: ServiceStatus = useMemo(() => {
    if (services.some((s) => s.status === "outage")) return "outage";
    if (services.some((s) => s.status === "degraded")) return "degraded";
    if (services.every((s) => s.status === "operational" || s.status === "unknown"))
      return "operational";
    return "unknown";
  }, [services]);

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="font-display text-foreground text-xl font-semibold tracking-tight">
            System health
          </h2>
          <p className="text-foreground/55 text-xs">
            Live readiness for each backing service. Auto-refreshes every 30s.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setAuto((a) => !a)}
            className={cn(
              "border-foreground/15 inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 font-mono text-[11px] uppercase tracking-wider transition-colors",
              auto
                ? "bg-foreground text-background border-foreground"
                : "text-foreground/65 hover:text-foreground hover:border-foreground/40",
            )}
          >
            <span
              aria-hidden
              className={cn("h-1.5 w-1.5 rounded-full", auto ? "bg-brand animate-pulse" : "bg-foreground/40")}
            />
            Auto-refresh {auto ? "on" : "off"}
          </button>
          <Button size="sm" variant="outline" onClick={load} className="rounded-full">
            <RefreshCw className={cn("mr-2 h-3.5 w-3.5", loading && "animate-spin")} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Overall banner */}
      <section
        className={cn(
          "border-foreground/10 bg-card relative overflow-hidden rounded-3xl border p-6 sm:p-8",
        )}
      >
        <div className="bg-brand/[0.06] pointer-events-none absolute -right-32 -top-32 h-72 w-72 rounded-full blur-[120px]" />
        <div className="relative flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <span
              className={cn(
                "flex h-12 w-12 items-center justify-center rounded-full",
                overall === "operational"
                  ? "bg-brand/15 text-foreground"
                  : overall === "outage"
                    ? "bg-destructive/15 text-destructive"
                    : "bg-yellow-500/15 text-yellow-500",
              )}
            >
              {overall === "outage" ? (
                <AlertCircle className="h-5 w-5" />
              ) : (
                <CheckCircle2 className="h-5 w-5" />
              )}
            </span>
            <div>
              <p className="text-foreground/55 font-mono text-[11px] uppercase tracking-wider">
                Overall
              </p>
              <p className="font-display text-foreground mt-0.5 text-2xl font-bold tracking-tight">
                {overall === "operational"
                  ? "All systems operational"
                  : overall === "outage"
                    ? "Active outage"
                    : overall === "degraded"
                      ? "Degraded performance"
                      : "Status unknown"}
              </p>
            </div>
          </div>
          {lastChecked && (
            <span className="text-foreground/55 font-mono text-[11px] uppercase tracking-wider">
              Checked {lastChecked.toLocaleTimeString()}
            </span>
          )}
        </div>
      </section>

      {/* Per-service grid */}
      {loading && !resp ? (
        <LoadingState variant="stats" rows={6} />
      ) : error ? (
        <div className="border-destructive/30 bg-destructive/[0.04] rounded-2xl border p-6 text-center">
          <AlertCircle className="text-destructive mx-auto h-6 w-6" />
          <p className="text-foreground mt-3 text-sm font-medium">Couldn&apos;t fetch health</p>
          <p className="text-foreground/65 mt-1 text-xs">{error}</p>
        </div>
      ) : (
        <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {services.map((s) => (
            <li
              key={s.key}
              className="border-foreground/10 bg-card flex flex-col gap-3 rounded-2xl border p-5"
            >
              <div className="flex items-start justify-between gap-3">
                <div className="flex items-center gap-3">
                  <span className="bg-foreground/8 text-foreground inline-flex h-9 w-9 items-center justify-center rounded-full">
                    <s.icon className="h-4 w-4" />
                  </span>
                  <div>
                    <p className="text-foreground font-display text-sm font-semibold">{s.name}</p>
                    <p className="text-foreground/55 text-xs">{s.description}</p>
                  </div>
                </div>
                <span
                  className={cn(
                    "inline-flex shrink-0 items-center gap-1 rounded-full border px-2 py-0.5 font-mono text-[10px] font-semibold uppercase tracking-wider",
                    STATUS_TONE[s.status],
                  )}
                >
                  <span
                    aria-hidden
                    className={cn(
                      "h-1 w-1 rounded-full",
                      STATUS_DOT[s.status],
                      s.status === "operational" && "animate-pulse",
                    )}
                  />
                  {STATUS_LABEL[s.status]}
                </span>
              </div>
              <div className="border-foreground/8 mt-1 flex items-center justify-between gap-3 border-t pt-3 font-mono text-[10px] uppercase tracking-wider text-foreground/55">
                <span>{s.uptime90d.toFixed(2)}% · 90d</span>
                {typeof s.latencyMs === "number" && <span>p50 {s.latencyMs}ms</span>}
              </div>
            </li>
          ))}
        </ul>
      )}

      <p className="text-foreground/45 inline-flex items-center gap-2 font-mono text-[11px] uppercase tracking-wider">
        Backend wishlist: <code className="font-mono">/health/ready</code> with per-service detail.
        90d uptime is currently illustrative.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useTranslations } from "next-intl";
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  ChevronLeft,
  ChevronRight,
  ExternalLink,
  Search,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { useAdminConversations } from "@/hooks";
import { cn } from "@/lib/utils";

const PAGE_SIZE_OPTIONS = [25, 50, 100] as const;
type SortDir = "asc" | "desc";
type ConvSortKey = "title" | "owner" | "messages" | "created_at" | "updated_at";
type Status = "active" | "archived" | "all";

function getInitials(nameOrEmail: string): string {
  return nameOrEmail
    .split(/[\s@]/)
    .filter(Boolean)
    .slice(0, 2)
    .map((s) => s[0]?.toUpperCase() ?? "")
    .join("");
}

function UserAvatar({
  userId,
  label,
  size = "md",
}: {
  userId: string | null | undefined;
  label: string;
  size?: "sm" | "md";
}) {
  const cls = size === "sm" ? "h-6 w-6 text-[10px]" : "h-7 w-7 text-[11px]";
  return (
    <Avatar className={cls}>
      {userId && <AvatarImage src={`/api/users/avatar/${userId}`} alt={label} />}
      <AvatarFallback>{getInitials(label)}</AvatarFallback>
    </Avatar>
  );
}

export default function AdminConversationsPage() {
  const t = useTranslations("admin");
  const { conversations, conversationsTotal, users, isLoading, fetchConversations, fetchUsers } =
    useAdminConversations();

  const [search, setSearch] = useState("");
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
  const [status, setStatus] = useState<Status>("active");
  const [pageSize, setPageSize] = useState<number>(50);
  const [page, setPage] = useState(0);
  const [sort, setSort] = useState<{ by: ConvSortKey; dir: SortDir }>({
    by: "updated_at",
    dir: "desc",
  });

  // Reset to first page when filters/sort change
  useEffect(() => {
    setPage(0);
  }, [search, selectedUserId, status, pageSize, sort.by, sort.dir]);

  // Load owners list for the dropdown — once on mount, independent of any tab.
  useEffect(() => {
    fetchUsers({ limit: 200, sort_by: "email", sort_dir: "asc" });
  }, [fetchUsers]);

  // Debounced fetch for the conversations table.
  useEffect(() => {
    const timer = setTimeout(() => {
      fetchConversations({
        search: search || undefined,
        user_id: selectedUserId || undefined,
        status,
        sort_by: sort.by,
        sort_dir: sort.dir,
        skip: page * pageSize,
        limit: pageSize,
      });
    }, 300);
    return () => clearTimeout(timer);
  }, [search, selectedUserId, status, sort.by, sort.dir, page, pageSize, fetchConversations]);

  const totalPages = Math.max(1, Math.ceil(conversationsTotal / pageSize));

  const toggleSort = (key: ConvSortKey) =>
    setSort((s) =>
      s.by === key ? { by: key, dir: s.dir === "asc" ? "desc" : "asc" } : { by: key, dir: "desc" },
    );

  const userOptions = useMemo(
    () => users.map((u) => ({ id: u.id, email: u.email, fullName: u.full_name })),
    [users],
  );

  return (
    <div className="flex h-full flex-col">
      <div className="mb-6">
        <p className="text-foreground/55 font-mono text-[11px] tracking-wider uppercase">
          Conversations
        </p>
        <h2 className="font-display text-foreground mt-1 text-xl font-semibold tracking-tight">
          {t("conversationsTitle")}
        </h2>
        <p className="text-foreground/65 mt-1 text-sm">{t("conversationsDesc")}</p>
      </div>

      <div className="mb-4 flex flex-wrap items-center gap-2">
        <div className="relative min-w-[240px] flex-1">
          <Search className="text-muted-foreground absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2" />
          <Input
            placeholder={t("search")}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-10"
          />
        </div>

        <Select value={status} onValueChange={(v) => setStatus(v as Status)}>
          <SelectTrigger className="w-[140px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="active">Active</SelectItem>
            <SelectItem value="archived">Archived</SelectItem>
            <SelectItem value="all">All</SelectItem>
          </SelectContent>
        </Select>

        <Select
          value={selectedUserId ?? "all"}
          onValueChange={(v) => setSelectedUserId(v === "all" ? null : v)}
        >
          <SelectTrigger className="w-[260px]">
            <SelectValue placeholder="All owners" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All owners</SelectItem>
            {userOptions.map((u) => (
              <SelectItem key={u.id} value={u.id}>
                <span className="flex items-center gap-2">
                  <UserAvatar userId={u.id} label={u.fullName || u.email} size="sm" />
                  <span className="truncate">{u.email}</span>
                </span>
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select value={String(pageSize)} onValueChange={(v) => setPageSize(Number(v))}>
          <SelectTrigger className="w-[110px]">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {PAGE_SIZE_OPTIONS.map((n) => (
              <SelectItem key={n} value={String(n)}>
                {n} / page
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="text-muted-foreground mb-2 text-xs">{conversationsTotal} total</div>

      <Table>
        <TableHeader>
          <TableRow>
            <SortableHead
              active={sort.by === "title"}
              dir={sort.dir}
              onClick={() => toggleSort("title")}
            >
              {t("title")}
            </SortableHead>
            <SortableHead
              active={sort.by === "owner"}
              dir={sort.dir}
              onClick={() => toggleSort("owner")}
            >
              {t("owner")}
            </SortableHead>
            <SortableHead
              active={sort.by === "messages"}
              dir={sort.dir}
              onClick={() => toggleSort("messages")}
            >
              {t("messages")}
            </SortableHead>
            <SortableHead
              active={sort.by === "created_at"}
              dir={sort.dir}
              onClick={() => toggleSort("created_at")}
            >
              {t("created")}
            </SortableHead>
            <TableHead>{t("status")}</TableHead>
            <TableHead />
          </TableRow>
        </TableHeader>
        <TableBody>
          {isLoading && conversations.length === 0
            ? Array.from({ length: 5 }).map((_, i) => (
                <TableRow key={i}>
                  {Array.from({ length: 6 }).map((__, j) => (
                    <TableCell key={j}>
                      <Skeleton className="h-4 w-full" />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            : conversations.map((conv) => (
                <TableRow key={conv.id}>
                  <TableCell className="font-medium">{conv.title || t("untitled")}</TableCell>
                  <TableCell>
                    {conv.user_email ? (
                      <span className="flex items-center gap-2">
                        <UserAvatar
                          userId={conv.user_id ?? null}
                          label={conv.user_email}
                          size="sm"
                        />
                        <span className="text-muted-foreground truncate">{conv.user_email}</span>
                      </span>
                    ) : (
                      <span className="text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>{conv.message_count}</TableCell>
                  <TableCell>{new Date(conv.created_at).toLocaleDateString()}</TableCell>
                  <TableCell>
                    {conv.is_archived ? (
                      <Badge variant="secondary">Archived</Badge>
                    ) : (
                      <Badge variant="default">Active</Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    <Link
                      href={`/chat?id=${conv.id}`}
                      className="text-foreground/40 hover:text-foreground inline-flex items-center gap-1 font-mono text-[11px] tracking-wider uppercase transition-colors"
                    >
                      <ExternalLink className="h-3 w-3" />
                      {t("view")}
                    </Link>
                  </TableCell>
                </TableRow>
              ))}
          {!isLoading && conversations.length === 0 && (
            <TableRow>
              <TableCell colSpan={6} className="text-muted-foreground py-8 text-center">
                {t("noConversations")}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      <PaginationBar
        page={page}
        pageSize={pageSize}
        total={conversationsTotal}
        totalPages={totalPages}
        isLoading={isLoading}
        onPrev={() => setPage((p) => Math.max(0, p - 1))}
        onNext={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
      />
    </div>
  );
}

function SortableHead({
  active,
  dir,
  onClick,
  children,
}: {
  active: boolean;
  dir: SortDir;
  onClick: () => void;
  children: React.ReactNode;
}) {
  const Icon = !active ? ArrowUpDown : dir === "asc" ? ArrowUp : ArrowDown;
  return (
    <TableHead>
      <button
        type="button"
        onClick={onClick}
        className={cn(
          "hover:text-foreground inline-flex items-center gap-1 text-left transition-colors",
          active && "text-foreground",
        )}
      >
        {children}
        <Icon className={cn("h-3 w-3", !active && "opacity-40")} aria-hidden />
      </button>
    </TableHead>
  );
}

function PaginationBar({
  page,
  pageSize,
