      const data = await apiClient
        .get<{ items: StripeEvent[] }>("/admin/stripe-events?limit=500")
        .catch(() => null);
      if (data) {
        setEvents(data.items);
        setUsingStub(false);
      } else {
        setEvents(STUB_EVENTS);
        setUsingStub(true);
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
