        {/* Featured Credits card — spans 2 cols */}
        <FeaturedCreditsCard
          balance={credits?.balance}
          loading={creditsLoading}
          spark={creditsSpark}
          delta={creditsDelta}
          deltaLabel={deltaLabel}
