        />
        {%- endif %}
        <StatCard
          label="Conversations"
          value={convLoading ? "—" : (conversations?.total ?? 0).toLocaleString()}
          icon={MessageSquare}
          loading={convLoading}
        />
        {%- if cookiecutter.enable_credits_system %}
        <StatCard
          label={`API calls (${period}d)`}
          value={timeline ? callsSpark.reduce((a, b) => a + b, 0).toLocaleString() : "—"}
          icon={Activity}
