@import "tailwindcss";

/* =========================================================================
   Design tokens — single brand var drives the whole app.
   Change `--brand-h` / `--brand-c` to retheme.
   Section-level dark/light: wrap with `.theme-dark` or `.theme-light`.
   ========================================================================= */

@theme {
  /* ============================================================
     Brand — preset chosen at template-generation time via
     `--brand-color` CLI flag. Each preset is tuned so contrast
     on dark + light themes works. Users can override at runtime
     via the in-app picker (/settings/appearance), which writes
     CSS variables on `<html>`.
     ============================================================ */
{%- if cookiecutter.brand_color == "blue" %}
  /* Preset: BLUE (Stripe / Vercel — classic SaaS) */
  --brand-h: 250;
  --brand-c: 0.20;
  --brand-l: 65%;
  --color-brand-foreground: oklch(98% 0 0);
{%- elif cookiecutter.brand_color == "green" %}
  /* Preset: GREEN (calm, fresh, healthtech) */
  --brand-h: 155;
  --brand-c: 0.18;
  --brand-l: 65%;
  --color-brand-foreground: oklch(98% 0 0);
{%- elif cookiecutter.brand_color == "red" %}
  /* Preset: RED (warm, energetic) */
  --brand-h: 25;
  --brand-c: 0.20;
  --brand-l: 60%;
  --color-brand-foreground: oklch(98% 0 0);
{%- elif cookiecutter.brand_color == "violet" %}
  /* Preset: VIOLET (Linear / Anthropic — modern AI) */
  --brand-h: 295;
  --brand-c: 0.22;
  --brand-l: 65%;
  --color-brand-foreground: oklch(98% 0 0);
{%- elif cookiecutter.brand_color == "orange" %}
  /* Preset: ORANGE (warm, friendly, B2C) */
  --brand-h: 55;
  --brand-c: 0.18;
  --brand-l: 72%;
  --color-brand-foreground: oklch(15% 0 0);
{%- else %}
  /* Preset: BLUE (default fallback) */
  --brand-h: 250;
  --brand-c: 0.20;
  --brand-l: 65%;
  --color-brand-foreground: oklch(98% 0 0);
{%- endif %}

  --color-brand: oklch(var(--brand-l) var(--brand-c) var(--brand-h));
  --color-brand-hover: oklch(calc(var(--brand-l) - 8%) var(--brand-c) var(--brand-h));
  --color-brand-muted: oklch(var(--brand-l) calc(var(--brand-c) * 0.4) var(--brand-h));
  /* Chart strokes/fills — defaults to a darker brand variant so charts stay
     readable on light backgrounds even when the brand itself is high-lightness
     (e.g. lime). Dark themes override this to use the bright brand directly. */
  --color-chart: oklch(55% var(--brand-c) var(--brand-h));

  /* Light theme — cream */
  --color-background: oklch(96% 0.005 90);
  --color-foreground: oklch(15% 0 0);
  --color-card: oklch(100% 0 0);
  --color-card-foreground: oklch(15% 0 0);
  --color-popover: oklch(100% 0 0);
  --color-popover-foreground: oklch(15% 0 0);
  --color-primary: oklch(15% 0 0);
  --color-primary-foreground: oklch(98% 0 0);
  --color-secondary: oklch(93% 0.005 90);
  --color-secondary-foreground: oklch(20% 0 0);
  --color-muted: oklch(93% 0.005 90);
  --color-muted-foreground: oklch(45% 0 0);
  --color-accent: oklch(93% 0.005 90);
  --color-accent-foreground: oklch(20% 0 0);
  --color-destructive: oklch(57.7% 0.245 27.325);
  --color-destructive-foreground: oklch(98.5% 0 0);
  --color-border: oklch(88% 0.005 90);
  --color-input: oklch(88% 0.005 90);
  --color-ring: var(--color-brand);

  /* Radius */
  --radius: 0.5rem;
  --radius-card: 1rem;
  --radius-pill: 999px;

  /* Typography */
  --font-display: var(--font-display), "Bricolage Grotesque", system-ui, sans-serif;
  --font-body: var(--font-body), "Inter", system-ui, sans-serif;
  --font-accent: var(--font-display), "Bricolage Grotesque", system-ui, sans-serif;
  --font-mono: var(--font-mono), "Geist Mono", ui-monospace, "SF Mono", Menlo, monospace;

  /* Motion */
