"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
{%- if cookiecutter.enable_teams and cookiecutter.enable_rag %}
  Database,
{%- endif %}
  LayoutDashboard,
  MessageSquare,
  Search,
  Settings,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

import { useAuth } from "@/hooks";
import { ROUTES } from "@/lib/constants";
import { cn } from "@/lib/utils";

interface TabItem {
  label: string;
  href?: string;
  icon: LucideIcon;
  /** When true, treat as active if pathname starts with `href`. */
  startsWith?: boolean;
  onClick?: () => void;
}

export function MobileTabBar() {
  const pathname = usePathname();
  const router = useRouter();
  const { user } = useAuth();

  const stripped = pathname.replace(/^\/[a-z]{2}/, "");

  const items: TabItem[] = [
    { label: "Chat", href: ROUTES.CHAT, icon: MessageSquare, startsWith: true },
{%- if cookiecutter.enable_teams and cookiecutter.enable_rag %}
    { label: "KB", href: ROUTES.KB, icon: Database, startsWith: true },
{%- endif %}
    {
      label: "Home",
      href: user?.role === "admin" ? ROUTES.DASHBOARD : ROUTES.CHAT,
      icon: LayoutDashboard,
    },
    {
      label: "Search",
      icon: Search,
      onClick: () => {
        // Trigger global ⌘K command palette via synthetic keyboard event.
        const event = new KeyboardEvent("keydown", {
          key: "k",
          metaKey: true,
          bubbles: true,
        });
        document.dispatchEvent(event);
      },
    },
    { label: "Settings", href: ROUTES.SETTINGS, icon: Settings, startsWith: true },
  ];

  const isActive = (item: TabItem) => {
    if (!item.href) return false;
    if (item.startsWith) return stripped === item.href || stripped.startsWith(item.href + "/");
    return stripped === item.href;
  };

  return (
    <nav
      role="navigation"
      aria-label="Primary"
      className="border-foreground/10 bg-background/95 supports-[backdrop-filter]:bg-background/85 fixed inset-x-0 bottom-0 z-40 flex items-stretch justify-around border-t backdrop-blur-md pb-[env(safe-area-inset-bottom)] lg:hidden"
    >
      {items.map((item) => {
        const active = isActive(item);
        const className = cn(
          "flex flex-1 flex-col items-center justify-center gap-1 py-2.5 text-[10px] font-medium uppercase tracking-wider transition-colors min-h-[56px]",
          active ? "text-foreground" : "text-foreground/55 hover:text-foreground",
        );
        const inner = (
          <>
            <item.icon
              className={cn(
                "h-5 w-5 transition-transform",
                active && "text-foreground scale-110",
              )}
            />
            <span className="font-mono">{item.label}</span>
            {active && (
              <span aria-hidden className="bg-brand absolute top-0 h-0.5 w-8 rounded-full" />
            )}
          </>
        );
        if (item.onClick) {
          return (
            <button
              key={item.label}
              type="button"
              onClick={item.onClick}
              aria-label={item.label}
              className={cn(className, "relative")}
            >
              {inner}
            </button>
          );
        }
        return (
          <Link
            key={item.label}
            href={item.href!}
            aria-label={item.label}
            aria-current={active ? "page" : undefined}
            className={cn(className, "relative")}
            onClick={(e) => {
              if (item.href === stripped) {
                e.preventDefault();
                router.refresh();
              }
            }}
          >
            {inner}
          </Link>
        );
      })}
    </nav>
  );
}

