def normalize_tool_args(args: Any) -> dict[str, Any]:
    """Coerce a tool-call ``args`` payload to a dict (handles JSON strings + None)."""
    if isinstance(args, str):
        return json.loads(args) if args.strip() else {}
    if args is None:
        return {}
    return args


